import React from 'react';
import greenleader from "../assets/greenleaders.jpeg";
import clientbill from "../assets/clientbill.jpg";
import navmed from "../assets/navmed.png";
import smart from "../assets/smart.jpg";
import eldocity from "../assets/eldocitylogo.jpeg";
import Diamond from "../assets/Diamond.jpeg";

const clients = [
  { name: navmed, url: 'https://client1.com', alt: 'Navmed Logo' },
  { name: clientbill, url: 'https://billwayssacco.co.ke', alt: 'Client Bill Logo' },
  { name: smart, url: 'https://client3.com', alt: 'Smart Logo' },
  { name: greenleader, url: 'https://stickywest.github.io/green/', alt: 'Green Leader Logo' },
  { name: eldocity, url: 'https://stickywest.github.io/eldocity/', alt: 'Eldo City Logo' },
  { name: Diamond, url: 'https://diamonddovetours.com', alt: 'Diamond Dove TOurs' },
];

const HappyClients: React.FC = () => {
  return (
    <div className="w-full bg-gradient-to-br from-gray-50 to-gray-100 py-12 md:py-20">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <h2 className="text-2xl sm:text-3xl md:text-4xl font-bold text-center text-gray-800 mb-8 md:mb-12">
          Trusted by World-Class Clients
        </h2>
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-6 place-items-center animate-fadeInUp">
          {clients.map((client, index) => (
            <a
              key={index}
              href={client.url}
              target="_blank"
              rel="noopener noreferrer"
              className="group relative w-28 h-28 sm:w-32 sm:h-32 md:w-36 md:h-36 lg:w-40 lg:h-40 flex items-center justify-center rounded-lg bg-white backdrop-blur-md shadow-md hover:shadow-2xl transition-transform duration-500 transform hover:-translate-y-2 border border-gray-200 hover:border-[#fdd910] hover:rotate-3"
            >
              <img
                src={client.name}
                alt={client.alt}
                className="w-20 h-20 sm:w-24 sm:h-24 md:w-28 md:h-28 lg:w-32 lg:h-32 object-contain transition-transform duration-500 group-hover:scale-110 group-hover:rotate-6"
                loading="lazy"
              />
            </a>
          ))}
        </div>
      </div>
    </div>
  );
};

export default HappyClients;
