import React from 'react';
import { Link } from 'react-router-dom';
import HappyClients from '../components/HappyClients';
//import CompanySection from '../components/CompanySection';
import Hero from '../components/HeroSection'; // Import the Hero component

const Home: React.FC = () => {
  return (
    <div className="flex flex-col items-center justify-center min-h-screen text-white font-sans bg-gray-100">
      {/* Hero Section */}
      <Hero />

      {/* Services Section */}
      <section className="w-full py-16 bg-gradient-to-b from-gray-100 to-white" aria-label="Our Services">
        <h2 className="text-4xl text-center font-extrabold text-gray-800 mb-10">
          Our Services
        </h2>
        <div className="max-w-7xl mx-auto px-6 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-10">
          {[
            { 
              title: "Product Design", 
              description: "Innovative and sustainable product design services tailored to your needs.", 
              link: "/Services", 
              icon: "fa-cogs" 
            },
            { 
              title: "Web Design", 
              description: "Custom web design solutions that are both aesthetically pleasing and functional.", 
              link: "/Services", 
              icon: "fa-desktop" 
            },
            { 
              title: "System Development", 
              description: "End-to-end system development services to streamline your business processes.", 
              link: "/Services", 
              icon: "fa-code" 
            },
            { 
              title: "Artificial Intelligence", 
              description: "AI solutions that drive efficiency and innovation in your organization.", 
              link: "/Services", 
              icon: "fa-robot" 
            },
          ].map((service, index) => (
            <Link
              key={index}
              to={service.link}
              className="block group transform hover:scale-105 transition-transform duration-500"
              aria-label={`Learn more about ${service.title}`}
            >
              <div className="relative p-6 bg-white bg-opacity-80 backdrop-blur-md shadow-lg rounded-2xl overflow-hidden border border-gray-200 hover:shadow-2xl transition-shadow duration-500">
                {/* Icon Section */}
                <div className="relative bg-white p-6 rounded-lg text-center transform hover:scale-105 transition-transform duration-300 shadow-lg">
                  <div
                    className="absolute -top-6 left-1/2 transform -translate-x-1/2 bg-yellow-400 text-white p-4 rounded-full shadow-lg group-hover:scale-110 transition-transform duration-500"
                    style={{ clipPath: 'circle(50% at 50% 50%)' }}
                  >
                    <i className={`fa ${service.icon} text-3xl`} aria-hidden="true" />
                  </div>
                </div>

                {/* Card Content */}
                <div className="pt-8 text-center">
                  <h3 className="text-2xl font-extrabold text-gray-800 mb-2">
                    {service.title}
                  </h3>
                  <p className="text-gray-600 leading-relaxed mb-4">
                    {service.description}
                  </p>
                  <div className="flex items-center justify-center">
                    <span className="inline-block px-4 py-2 bg-yellow-400 text-white font-semibold rounded-full hover:bg-yellow-500 transition duration-300">
                      Learn More
                    </span>
                  </div>
                </div>

                {/* Background Shine */}
                <div className="absolute inset-0 opacity-0 group-hover:opacity-20 transition duration-500 bg-gradient-to-br from-yellow-300 to-yellow-600" />
              </div>
            </Link>
          ))}
        </div>
      </section>

      {/* About Our Company Section */}
      {/*<CompanySection />*/}

      {/* Happy Clients Section */}
      <section className="w-full max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12" aria-label="Happy Clients">
        <HappyClients />
      </section>

      {/* Community Section */}
      <section className="w-full py-16 bg-gray-50" aria-label="Community">
        {/* Add community-related content here */}
      </section>
    </div>
  );
};

export default Home;